using System.Collections;
using UnityEngine;
namespace CafeLife {
 public sealed class CafeEspressoFlow:MonoBehaviour {
  CafeGame game;Transform liquid,crema,stream;Vector3 spout,bottom;Mesh cupMesh;bool staff;float elapsed,duration;public float Progress {get;private set;}
  public static CafeEspressoFlow Begin(CafeGame game,bool staff=false,float duration=5){var root=new GameObject(staff?"Barista görünür espresso hazırlığı":"Oyuncu görünür espresso hazırlığı");root.transform.SetParent(game.world.transform,false);var flow=root.AddComponent<CafeEspressoFlow>();flow.game=game;flow.staff=staff;flow.duration=duration;flow.Build();return flow;}
  void Build(){Transform nozzle=null;foreach(var t in game.GetComponent<CafePolish>().scenery.GetComponentsInChildren<Transform>(true))if(t.name=="Portafiltre çıkışı"){nozzle=t;if(!staff)break;}spout=nozzle?nozzle.position-Vector3.up*.027f:new Vector3(-.3f,1.403f,5.34f);bottom=spout-Vector3.up*.145f;transform.position=bottom;
   var vertices=new System.Collections.Generic.List<Vector3>();var triangles=new System.Collections.Generic.List<int>();for(int ring=0;ring<4;ring++)for(int i=0;i<=48;i++){float a=i*Mathf.PI*2/48;float r=ring==0?.052f:ring==1?.064f:ring==2?.059f:.047f;float y=ring==1||ring==2?.12f:.006f;vertices.Add(new Vector3(Mathf.Cos(a)*r,y,Mathf.Sin(a)*r));}for(int ring=0;ring<3;ring++)for(int i=0;i<48;i++){int a=ring*49+i,b=a+49;triangles.AddRange(new[]{a,b,a+1,a+1,b,b+1});}var mesh=new Mesh{name="İçi açık espresso fincanı"};cupMesh=mesh;mesh.SetVertices(vertices);mesh.SetTriangles(triangles,0);mesh.RecalculateNormals();var cup=new GameObject("Makine altındaki açık fincan",typeof(MeshFilter),typeof(MeshRenderer));cup.transform.SetParent(transform,false);cup.GetComponent<MeshFilter>().sharedMesh=mesh;cup.GetComponent<Renderer>().sharedMaterial=game.world.ColorMaterial(new Color(.87f,.84f,.73f));
   liquid=Disc("Yükselen espresso",new Color(.13f,.055f,.02f));crema=Disc("Espresso krema yüzeyi",new Color(.64f,.35f,.12f));stream=Disc("Portafiltreden akan espresso",new Color(.23f,.09f,.025f));var lamp=new GameObject("Grup başlığı çalışma ışığı").AddComponent<Light>();lamp.transform.SetParent(transform,false);lamp.transform.localPosition=new Vector3(0,.18f,.14f);lamp.type=LightType.Point;lamp.range=.55f;lamp.intensity=.045f;lamp.color=new Color(1,.85f,.65f);lamp.shadows=LightShadows.None;SetProgress(0);
  }
  void OnDestroy(){if(cupMesh)Destroy(cupMesh);}
  Transform Disc(string title,Color color){var part=GameObject.CreatePrimitive(PrimitiveType.Cylinder);part.name=title;part.transform.SetParent(transform,false);Destroy(part.GetComponent<Collider>());part.layer=2;part.GetComponent<Renderer>().sharedMaterial=game.world.ColorMaterial(color);return part.transform;}
  public void SetProgress(float value){Progress=Mathf.Clamp01(value);float height=.005f+Progress*.095f;liquid.localScale=new Vector3(.092f,height*.5f,.092f);liquid.localPosition=Vector3.up*(.008f+height*.5f);crema.localScale=new Vector3(.094f,.0015f,.094f);crema.localPosition=Vector3.up*(.0095f+height);float top=spout.y-bottom.y;stream.localPosition=Vector3.up*((top+.01f+height)*.5f);stream.localScale=new Vector3(.0045f,(top-.01f-height)*.5f,.0045f);}
  void Update(){if(!game)return;if(game.Paused)return;if(staff){elapsed+=Time.deltaTime;SetProgress(elapsed/duration);}else{if(game.cup==null){gameObject.SetActive(false);Destroy(gameObject);return;}if(game.brewTime>0)SetProgress(1-game.brewTime/Mathf.Max(.01f,game.brewTotal));else{SetProgress(Mathf.Clamp01(game.cup.yield/Mathf.Max(1,game.cup.dose*2.8f)));stream.gameObject.SetActive(false);}}}
  public IEnumerator StaffPour(){while(game&&elapsed<duration)yield return null;SetProgress(1);if(stream)stream.gameObject.SetActive(false);float pause=0;while(game&&pause<.35f){if(!game.Paused)pause+=Time.deltaTime;yield return null;}Destroy(gameObject);}
 }
}
